2. Define la función que lee el archivo y cuenta las apariciones de la palabra:

```c++
void contarApariciones(std::string nombreArchivo, std::string palabraBuscada) {
    std::ifstream archivo(nombreArchivo);
    if (!archivo) {
        std::cerr << "No se pudo abrir el archivo: " << nombreArchivo << std::endl;
        return;
    }

    std::string linea;
    int contador = 0;

    while (std::getline(archivo, linea)) {
        size_t posicion = 0;
        while ((posicion = linea.find(palabraBuscada, posicion)) != std::string::npos) {
            contador++;
            posicion += palabraBuscada.length();
        }
    }

    archivo.close();
    std::cout << "El número de apariciones de \"" << palabraBuscada << "\" en " << nombreArchivo << " es: " << contador << std::endl;
}
```

3. Llama a la función `contarApariciones()` con los nombres de archivo y la palabra de búsqueda:

```c++
